import{_ as e,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Cost of living basics","description":"What official sources say about tax, prices, utilities, transport and health card fees in Qatar, and where to see current figures.","frontmatter":{"title":"Cost of living basics","description":"What official sources say about tax, prices, utilities, transport and health card fees in Qatar, and where to see current figures.","lastChecked":"2026-10","sourceCount":8},"headers":[],"relativePath":"guide/cost-of-living.md","filePath":"guide/cost-of-living.md"}'),s={name:"guide/cost-of-living.md"};function n(i,a,f,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="cost-of-living-basics" tabindex="-1">Cost of living basics <a class="header-anchor" href="#cost-of-living-basics" aria-label="Permalink to &quot;Cost of living basics&quot;">​</a></h1><p>This page sticks to figures published by official bodies. It does not give typical rents or grocery bills, because the official releases used here report how prices change, not what a home or a basket of shopping costs.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="tax" tabindex="-1">Tax <a class="header-anchor" href="#tax" aria-label="Permalink to &quot;Tax&quot;">​</a></h2><ul><li>There is no personal income tax. The General Tax Authority says individuals pay no tax on salaries, wages or personal income.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></li><li>Excise tax raises the price of some goods. Tobacco products and energy drinks are taxed at 100 percent of the higher of the standard price or the retail price before tax.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>Sweetened drinks are taxed by sugar content: QAR 0.77 per litre at 5 to 7.99 g of sugar per 100 ml, and QAR 1.06 per litre at 8 g or more. Drinks under 5 g, and drinks with only artificial sweeteners and no added sugar, are exempt.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li></ul><h2 id="how-prices-are-moving" tabindex="-1">How prices are moving <a class="header-anchor" href="#how-prices-are-moving" aria-label="Permalink to &quot;How prices are moving&quot;">​</a></h2><p>The National Planning Council&#39;s Consumer Price Index tracks price changes against the same month a year earlier and the month before. The most recent release found when this page was checked covers June 2026.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li>The index reached 110.12 points (base year 2018), up 0.06 percent on May 2026 and 2.21 percent on June 2025.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>Compared with June 2025, food and beverages rose 12.74 percent, and housing, water, electricity, gas and other fuels rose 2.67 percent.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>Transport fell 0.92 percent over the same year.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li></ul><p>The Council links the increase to regional challenges that affected international supply chains.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></p><h2 id="electricity-and-water" tabindex="-1">Electricity and water <a class="header-anchor" href="#electricity-and-water" aria-label="Permalink to &quot;Electricity and water&quot;">​</a></h2><p>Kahramaa&#39;s tariff page has a calculator for electricity and water, so you can work out a bill from current rates. Moving in and paying bills are covered in <a href="./housing-and-utilities">Housing and renting</a>.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><h2 id="getting-around" tabindex="-1">Getting around <a class="header-anchor" href="#getting-around" aria-label="Permalink to &quot;Getting around&quot;">​</a></h2><ul><li>Visit Qatar says you can use the Doha Metro all day for a maximum of QAR 6.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li><li>You buy a travel card at station vending machines, and some retailers sell them too.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>Mowasalat runs the Karwa buses. Use its Karwa Journey Planner app to plan a trip, and see <a href="./transport">Transport</a> for more.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li></ul><h2 id="health-card" tabindex="-1">Health card <a class="header-anchor" href="#health-card" aria-label="Permalink to &quot;Health card&quot;">​</a></h2><p>Hamad Medical Corporation lists a health card fee of QR 100 for residents, adults or children, and QR 50 for Qatari and GCC citizens and for domestic staff. Manual workers applying for a new card are listed at QR 50.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><p>Replacing a lost card costs a non-Qatari QR 100 if the card is still valid, or QR 200 if it has expired.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></p><h2 id="wages" tabindex="-1">Wages <a class="header-anchor" href="#wages" aria-label="Permalink to &quot;Wages&quot;">​</a></h2><p>The National Human Rights Committee&#39;s 2021 booklet gives the minimum wage as QAR 1,000 a month, plus at least QAR 500 for housing and QAR 300 for food if your employer does not provide them. Check the current amounts with the Ministry of Labour.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></p><p>See also: <a href="./housing-and-utilities">Housing and renting</a>, <a href="./work-and-labour-rights">Work and labour rights</a>, <a href="./transport">Transport</a>, <a href="./health">Health</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>National Planning Council, <a href="https://www.npc.qa/en/statistics/pages/news/07082026.aspx" target="_blank" rel="noreferrer">Consumer Price Index (CPI) for June 2026</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>General Tax Authority, <a href="https://gta.gov.qa/en/investors" target="_blank" rel="noreferrer">Investors</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>General Tax Authority, <a href="https://gta.gov.qa/en/taxes-info" target="_blank" rel="noreferrer">Taxes information</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/CustomerService/Pages/Tariff.aspx" target="_blank" rel="noreferrer">Tariff</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Visit Qatar, <a href="https://visitqatar.com/intl-en/plan-your-trip/getting-around/doha-metro" target="_blank" rel="noreferrer">Doha Metro Guide: Tickets, Map and Service Hours</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Mowasalat, <a href="https://www.mowasalat.com/our-service/public-bus-transportation/" target="_blank" rel="noreferrer">Public Bus Transportation</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://www.hamad.qa/EN/Patient-Information/How-To-Get-A-Health-Card/Pages/default.aspx" target="_blank" rel="noreferrer">Obtaining and Renewing a Health Card</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>National Human Rights Committee, <a href="https://www.nhrc-qa.org/storage/publications/file_6666d6f57f82d_1718015733.pdf" target="_blank" rel="noreferrer">Worker&#39;s Pocket Booklet, sixth edition, December 2021</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',21)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
